document.addEventListener('DOMContentLoaded',()=>{const dataElement=document.getElementById('carousel-data');const projectsData=JSON.parse(dataElement?.dataset.projects||'[]');let currentIndex=0;let autoplayInterval=null;const carousel=document.querySelector('.carousel');const btnNext=document.querySelector('.carousel__btn--next');const btnPrev=document.querySelector('.carousel__btn--prev');const indicatorsContainer=document.querySelector('.carousel__indicators');if(carousel&&btnNext&&btnPrev&&indicatorsContainer&&projectsData.length>0){const slidesWrapper=document.createElement('div');slidesWrapper.classList.add('slides-wrapper');carousel.insertBefore(slidesWrapper,indicatorsContainer);projectsData.forEach((project,i)=>{const slide=document.createElement('div');slide.classList.add('carousel-slide');const img=document.createElement('img');const originalUrl=project.image||'/images/default.jpg';if(originalUrl.includes('cloudinary.com')){img.src=originalUrl.replace('/upload/','/upload/w_1920,f_auto,q_auto/');img.srcset=` ${originalUrl.replace('/upload/','/upload/w_800,f_auto,q_auto/')}800w,${originalUrl.replace('/upload/','/upload/w_1200,f_auto,q_auto/')}1200w,${originalUrl.replace('/upload/','/upload/w_1920,f_auto,q_auto/')}1920w `.trim();img.sizes='100vw';}else{img.src=originalUrl;}img.alt=project.title;if(i===0){img.fetchPriority='high';}else{img.loading='lazy';}const overlayClone=document.createElement('div');overlayClone.classList.add('carousel__overlay');const textDiv=document.createElement('div');textDiv.classList.add('carousel__text');const h3=document.createElement('h3');h3.textContent=project.title;const p=document.createElement('p');p.textContent=project.short_description||'';const a=document.createElement('a');a.href=`/projets/${project.slug}`;a.classList.add('carousel__link');a.setAttribute('data-slide-index',i);a.textContent='Voir le projet';textDiv.appendChild(h3);textDiv.appendChild(p);textDiv.appendChild(a);overlayClone.appendChild(textDiv);slide.appendChild(img);slide.appendChild(overlayClone);slidesWrapper.appendChild(slide);const dot=document.createElement('div');dot.classList.add('carousel__indicator');if(i===0)dot.classList.add('active');dot.addEventListener('click',()=>{showSlide(i);resetAutoplay();});indicatorsContainer.appendChild(dot);});const indicators=document.querySelectorAll('.carousel__indicator');function showSlide(index){slidesWrapper.style.transform=`translateX(-${index*100}%)`;indicators.forEach((dot,i)=>dot.classList.toggle('active',i===index));currentIndex=index;}function nextSlide(){showSlide((currentIndex+1)% projectsData.length);}function prevSlide(){showSlide((currentIndex-1+projectsData.length)% projectsData.length);}function startAutoplay(){autoplayInterval=setInterval(nextSlide,10000);}function stopAutoplay(){if(autoplayInterval){clearInterval(autoplayInterval);autoplayInterval=null;}}function resetAutoplay(){stopAutoplay();startAutoplay();}btnNext.addEventListener('click',()=>{nextSlide();resetAutoplay();});btnPrev.addEventListener('click',()=>{prevSlide();resetAutoplay();});let startX=0,endX=0;slidesWrapper.addEventListener('touchstart',e=>{startX=e.touches[0].clientX;stopAutoplay();});slidesWrapper.addEventListener('touchmove',e=>{endX=e.touches[0].clientX;});slidesWrapper.addEventListener('touchend',()=>{const diffX=endX-startX;if(Math.abs(diffX)>50){diffX>0 ? prevSlide(): nextSlide();}startAutoplay();});document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){prevSlide();resetAutoplay();}else if(e.key==='ArrowRight'){nextSlide();resetAutoplay();}});carousel.addEventListener('mouseenter',stopAutoplay);carousel.addEventListener('mouseleave',startAutoplay);carousel.addEventListener('click',(e)=>{if(e.target.classList.contains('carousel__link')){const slideIndex=e.target.getAttribute('data-slide-index');sessionStorage.setItem('carouselSlideIndex',slideIndex);}});const savedSlideIndex=sessionStorage.getItem('carouselSlideIndex');if(savedSlideIndex!==null){sessionStorage.removeItem('carouselSlideIndex');currentIndex=parseInt(savedSlideIndex,10);showSlide(currentIndex);}else{showSlide(currentIndex);}startAutoplay();}const burger=document.querySelector('.burger');const navLinksMobile=document.querySelector('.nav-links-mobile');if(burger&&navLinksMobile){burger.addEventListener('click',(e)=>{e.stopPropagation();burger.classList.toggle('active');navLinksMobile.classList.toggle('mobile-active');});const navItemsMobile=navLinksMobile.querySelectorAll('.nav-item-mobile');navItemsMobile.forEach(item=>{item.addEventListener('click',()=>{burger.classList.remove('active');navLinksMobile.classList.remove('mobile-active');});});document.addEventListener('click',(e)=>{if(!navLinksMobile.contains(e.target)&&!burger.contains(e.target)){burger.classList.remove('active');navLinksMobile.classList.remove('mobile-active');}});}const navLeft=document.querySelector('.nav-left');if(navLeft){navLeft.addEventListener('click',()=>{window.scrollTo({top: 0,behavior: 'smooth'});});}const projectLinks=document.querySelectorAll('.project-card__link');projectLinks.forEach((link,index)=>{link.addEventListener('click',()=>{sessionStorage.setItem('scrollToProject',index);});});const scrollToProject=sessionStorage.getItem('scrollToProject');if(scrollToProject!==null){sessionStorage.removeItem('scrollToProject');setTimeout(()=>{const projectCard=document.getElementById(`project-${scrollToProject}`);if(projectCard){projectCard.scrollIntoView({behavior: 'smooth',block: 'center'});}},100);}});